#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "seidel-2d.h"


/* Array initialization. */
static
void init_array (int n,
                 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Use a row pointer to improve locality and reduce address computation. */
  for (i = 0; i < n; i++)
  {
    DATA_TYPE* Ai = A[i];
    for (j = 0; j < n; j++)
      Ai[j] = ((DATA_TYPE) i * (j + 2) + 2) / n;
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
                 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations:
   - Keep the original Gauss-Seidel update order (t, i, j) unchanged.
   - Use row pointers (A[i-1], A[i], A[i+1]) to reduce address computation.
   - Implement a 3x3 sliding window in the inner j-loop. This reuses
     neighbor values across j and reduces the number of memory loads
     from ~9 per point to ~3 per interior point while preserving the
     exact update order and data dependencies.
*/
static
void kernel_seidel_2d [[gnu::flatten, gnu::noinline]] (int tsteps,
                                                       int n,
                                                       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  (void)tsteps; /* Parameters are kept for API compatibility; PolyBench uses _PB_TSTEPS/_PB_N. */
  (void)n;

  const int PB_N       = _PB_N;
  const int PB_TSTEPS  = _PB_TSTEPS;

  int t, i;

#pragma scop
  for (t = 0; t < PB_TSTEPS; ++t)
  {
    /* i runs from 1 to PB_N-2 (inclusive). Rewritten as i < PB_N-1. */
    for (i = 1; i < PB_N - 1; ++i)
    {
      /* Neighboring row pointers to improve spatial locality and
         reduce index arithmetic inside the j-loop. */
      DATA_TYPE * restrict rowm1 = A[i - 1];
      DATA_TYPE * restrict row   = A[i];
      DATA_TYPE * restrict rowp1 = A[i + 1];

      /* The inner Gauss-Seidel scan along j is inherently sequential
         (depends on A[i][j-1]), so we keep the order but use a sliding
         3x3 window to minimize memory traffic. */
      int j;

      /* Only executed when the j-loop body will run, i.e., PB_N >= 3.
         This matches the original condition j = 1..PB_N-2. */

      /* Initialize the 3x3 window for j = 1:
         For each of the three rows (i-1, i, i+1), we cache values at
         j-1, j, j+1 into registers:
           a_*_jm1 -> column j-1
           a_*_j   -> column j
           a_*_jp1 -> column j+1
       */
      DATA_TYPE a_m1_jm1 = rowm1[0];
      DATA_TYPE a_m1_j   = rowm1[1];
      DATA_TYPE a_m1_jp1 = rowm1[2];

      DATA_TYPE a_0_jm1  = row[0];
      DATA_TYPE a_0_j    = row[1];
      DATA_TYPE a_0_jp1  = row[2];

      DATA_TYPE a_p1_jm1 = rowp1[0];
      DATA_TYPE a_p1_j   = rowp1[1];
      DATA_TYPE a_p1_jp1 = rowp1[2];

      /* j runs from 1 to PB_N-2 (inclusive). Rewritten as j < PB_N-1. */
      for (j = 1; j < PB_N - 1; ++j)
      {
        /* Compute the 9-point average using the current window.
           This uses:
             - updated A[i][j-1] (a_0_jm1)
             - not-yet-updated A[i][j], A[i][j+1] (a_0_j, a_0_jp1)
             - already-updated A[i-1][*] and not-yet-updated A[i+1][*],
           exactly matching the original Gauss-Seidel dependence pattern. */
        DATA_TYPE sum =
            a_m1_jm1 + a_m1_j   + a_m1_jp1 +
            a_0_jm1  + a_0_j    + a_0_jp1  +
            a_p1_jm1 + a_p1_j   + a_p1_jp1;

        row[j] = sum / SCALAR_VAL(9.0);

        /* Advance the window to the right for the next j, if any.
           We must not read beyond the boundary, so we skip this on
           the last iteration (j == PB_N-2). */
        if (j < PB_N - 2)
        {
          const int jp2 = j + 2;

          /* Row i-1: shift right and load the new rightmost neighbor. */
          a_m1_jm1 = a_m1_j;
          a_m1_j   = a_m1_jp1;
          a_m1_jp1 = rowm1[jp2];

          /* Row i+1: shift right and load the new rightmost neighbor. */
          a_p1_jm1 = a_p1_j;
          a_p1_j   = a_p1_jp1;
          a_p1_jp1 = rowp1[jp2];

          /* Current row i:
             - Left neighbor for next j is the value we just updated (row[j]).
             - Center neighbor is the previous right neighbor (still old).
             - Right neighbor is loaded from memory (still old).
             This exactly preserves the Gauss-Seidel in-place update order. */
          a_0_jm1  = row[j];      /* newly updated A[i][j] */
          a_0_j    = a_0_jp1;     /* old A[i][j+1] */
          a_0_jp1  = row[jp2];    /* old A[i][j+2] */
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_seidel_2d (tsteps, n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
