    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations applied:
 *  - Introduce a restrict-qualified local pointer to the 2D array to
 *    help the compiler with alias analysis.
 *  - Convert division by 9.0 to multiplication by a precomputed
 *    reciprocal in DATA_TYPE.
 *  - Use a sliding 3x3 window along each row to reuse neighbour values
 *    across j and drastically reduce memory loads (from 9 loads per
 *    point to ~3 loads per point) while preserving the exact
 *    Gauss-Seidel update order and semantics.
 */
static
void kernel_seidel_2d [[gnu::flatten, gnu::noinline]] (int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  /* Local restrict-qualified view of the matrix. POLYBENCH_2D ensures
     a contiguous n-by-n layout, so aliasing through other pointers
     does not occur inside this kernel. */
  DATA_TYPE (* __restrict A_)[n] = A;

  const int t_max = _PB_TSTEPS;
  const int n_max = _PB_N;

  /* Reciprocal of 9.0 in the appropriate scalar type. */
  const DATA_TYPE coeff = SCALAR_VAL(1.0) / SCALAR_VAL(9.0);

#pragma scop
  for (int t = 0; t < t_max; ++t)
  {
    /* Loop over interior rows; boundary rows are left unchanged. */
    for (int i = 1; i < n_max - 1; ++i)
    {
      /* Row pointers for the three rows involved in the stencil. */
      DATA_TYPE * __restrict row_im1 = A_[i - 1];
      DATA_TYPE * __restrict row_i   = A_[i];
      DATA_TYPE * __restrict row_ip1 = A_[i + 1];

      const int j_min = 1;
      const int j_max = n_max - 2; /* last interior column (inclusive) */

      if (j_max < j_min)
        continue; /* No interior columns for this row. */

      /* --- Sliding 3x3 window along the row ---------------------------------
       *
       * We maintain a 3-element window for each of the three rows:
       *   row_im1: p0, p1, p2   (previous row)
       *   row_i  : c0, c1, c2   (current row)
       *   row_ip1: n0, n1, n2   (next row)
       *
       * At column j, these represent:
       *   p0 = A[i-1][j-1], p1 = A[i-1][j], p2 = A[i-1][j+1]
       *   c0 = A[i  ][j-1], c1 = A[i  ][j], c2 = A[i  ][j+1]
       *   n0 = A[i+1][j-1], n1 = A[i+1][j], n2 = A[i+1][j+1]
       *
       * After computing the new value at (i,j), we:
       *   - shift the windows to the right (j <- j+1) by reusing
       *     p1/p2, c1/c2, n1/n2 and loading only the new rightmost
       *     elements at column j+2;
       *   - for the current row, we set c0 to the updated A[i][j], so
       *     the left neighbour at (i,j+1) uses the newly computed value,
       *     exactly as in the original Gauss-Seidel scheme.
       *
       * This preserves the original update order and dependencies while
       * significantly improving data locality and reducing memory traffic.
       * -------------------------------------------------------------------- */

      /* Initialize the window for j = j_min (uses columns 0,1,2). */
      DATA_TYPE p0 = row_im1[j_min - 1];
      DATA_TYPE p1 = row_im1[j_min];
      DATA_TYPE p2 = row_im1[j_min + 1];

      DATA_TYPE c0 = row_i[j_min - 1];
      DATA_TYPE c1 = row_i[j_min];
      DATA_TYPE c2 = row_i[j_min + 1];

      DATA_TYPE n0 = row_ip1[j_min - 1];
      DATA_TYPE n1 = row_ip1[j_min];
      DATA_TYPE n2 = row_ip1[j_min + 1];

      if (j_min < j_max)
      {
        /* More than one interior column:
           slide the window for j = j_min .. j_max-1,
           then handle j = j_max separately. */
        for (int j = j_min; j < j_max; ++j)
        {
          /* Compute new A[i][j] using the current 3x3 window. */
          DATA_TYPE sum =
              p0 + p1 + p2 +
              c0 + c1 + c2 +
              n0 + n1 + n2;
          DATA_TYPE new_center = sum * coeff;
          row_i[j] = new_center;

          /* Advance the window to column j+1.
             Loads of [j+2] are safe because:
               j <= j_max - 1 <= (n_max - 2) - 1 = n_max - 3,
             so j + 2 <= n_max - 1 (within the allocated row). */

          /* Previous row (i-1). */
          p0 = p1;
          p1 = p2;
          p2 = row_im1[j + 2];

          /* Current row (i). Left neighbour becomes the newly updated value. */
          c0 = new_center;
          c1 = c2;
          c2 = row_i[j + 2];

          /* Next row (i+1). */
          n0 = n1;
          n1 = n2;
          n2 = row_ip1[j + 2];
        }

        /* Final interior column j = j_max: the window already corresponds
           to this column after the loop above. */
        {
          const DATA_TYPE sum =
              p0 + p1 + p2 +
              c0 + c1 + c2 +
              n0 + n1 + n2;
          row_i[j_max] = sum * coeff;
        }
      }
      else
      {
        /* Exactly one interior column in this row: j_min == j_max.
           Just compute it once, no sliding needed. */
        const DATA_TYPE sum =
            p0 + p1 + p2 +
            c0 + c1 + c2 +
            n0 + n1 + n2;
        row_i[j_min] = sum * coeff;
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_seidel_2d (tsteps, n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
