    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   This implementation keeps the original Gauss–Seidel update order
   (t, then i, then j) exactly, but:
     - uses a restrict-qualified pointer to help the compiler with
       alias analysis,
     - introduces a tunable blocking factor in the i-dimension that
       preserves lexicographic order,
     - reduces inner-loop address arithmetic by using row pointers,
     - replaces the inner-loop division by a single precomputed
       multiplication factor.

   All transformations are semantics-preserving with respect to the
   original code.
*/
static void __attribute__((noinline, hot))
kernel_seidel_2d(int tsteps,
                 int n,
                 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  /* Parameters are kept for API compatibility; PolyBench’s _PB_*
   * macros define the actual loop bounds used for timing and DCE.
   */
  (void)tsteps;
  (void)n;

  /* Local restrict-qualified view of the 2D array.
   * PolyBench allocators return non-aliasing, contiguous storage, so
   * this is a valid and helpful assumption for the optimizer.
   */
  DATA_TYPE (*restrict Adata)[n] = (DATA_TYPE (*)[n])A;

  const int T     = _PB_TSTEPS;
  const int size  = _PB_N;

  if (size <= 2 || T <= 0)
    return; /* Nothing to update. */

  const int i_start = 1;
  const int i_end   = size - 2;
  const int j_start = 1;
  const int j_end   = size - 2;

  /* Precompute the reciprocal instead of dividing inside the inner
   * loop.  Modern compilers usually perform this optimization, but
   * spelling it out makes the intent explicit.
   */
  const DATA_TYPE c1 = SCALAR_VAL(1.0) / SCALAR_VAL(9.0);

#pragma scop
  for (int t = 0; t < T; ++t)
  {
    /* 1D blocking in the i-dimension.
     *
     * Order of (i,j) iterations remains:
     *   (1,1..), (2,1..), ..., (N-2,1..)
     * exactly as in the original kernel, so Gauss–Seidel
     * dependencies are preserved.
     */
    for (int ii = i_start; ii <= i_end; ii += KERNEL_SEIDEL_2D_I_BLOCK)
    {
      const int i_max = (ii + KERNEL_SEIDEL_2D_I_BLOCK - 1 <= i_end)
                        ? (ii + KERNEL_SEIDEL_2D_I_BLOCK - 1)
                        : i_end;

      for (int i = ii; i <= i_max; ++i)
      {
        /* Row pointers: we touch three neighboring rows for every
         * point update.  Making this explicit reduces index
         * arithmetic in the hot inner loop and clarifies the memory
         * access pattern for the compiler.
         */
        DATA_TYPE *restrict Aim1 = Adata[i - 1];
        DATA_TYPE *restrict Ai   = Adata[i];
        DATA_TYPE *restrict Aip1 = Adata[i + 1];

        for (int j = j_start; j <= j_end; ++j)
        {
          const DATA_TYPE a11 = Aim1[j - 1];
          const DATA_TYPE a12 = Aim1[j];
          const DATA_TYPE a13 = Aim1[j + 1];

          const DATA_TYPE a21 = Ai[j - 1];
          const DATA_TYPE a22 = Ai[j];
          const DATA_TYPE a23 = Ai[j + 1];

          const DATA_TYPE a31 = Aip1[j - 1];
          const DATA_TYPE a32 = Aip1[j];
          const DATA_TYPE a33 = Aip1[j + 1];

          Ai[j] = (a11 + a12 + a13 +
                   a21 + a22 + a23 +
                   a31 + a32 + a33) * c1;
        }
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_seidel_2d (tsteps, n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
