/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_seidel_2d[[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i;

  /* Local restricted view of the 2D array. This helps the compiler
     reason about aliasing and keeps the subscript expressions simple. */
  DATA_TYPE (*restrict a)[n] = A;

  /* These parameters are kept for interface compatibility; the actual
     loop bounds are derived from the PolyBench macros below. */
  (void)tsteps;
  (void)n;

  const int tsteps_pb = _PB_TSTEPS;
  const int n_pb      = _PB_N;

  /* If the problem is too small, there is nothing to update. */
  if (tsteps_pb <= 0 || n_pb < 3)
    return;

  /* Precompute the reciprocal once to avoid a division in the inner loop. */
  const DATA_TYPE inv9 = SCALAR_VAL(1.0) / SCALAR_VAL(9.0);

#pragma scop
  for (t = 0; t < tsteps_pb; ++t)
  {
    /* Iterate over the interior rows (boundary rows remain unchanged). */
    for (i = 1; i < n_pb - 1; ++i)
    {
      DATA_TYPE *restrict Ai   = a[i];
      DATA_TYPE *restrict Aim1 = a[i-1];
      DATA_TYPE *restrict Aip1 = a[i+1];

      const int last = n_pb - 2; /* last interior column index */

      if (last >= 1)
      {
        /* ------------------------------------------------------------------
         * Optimized 1D Gauss–Seidel sweep over columns using a 3×3
         * sliding window stencil. This transformation:
         *
         *   - Preserves the original update order exactly.
         *   - Ensures that A[i][j-1] used at column j is the value written
         *     at the previous column in the same time step (true Gauss–Seidel).
         *   - Reuses neighbor values across columns instead of reloading
         *     them from memory each time, significantly reducing memory
         *     traffic in the innermost loop.
         *
         * For each fixed (t, i), the original code was:
         *
         *   for (j = 1; j <= n_pb - 2; ++j)
         *     A[i][j] = avg of 3×3 neighborhood at (i,j)
         *
         * The logic below computes exactly the same sequence of updates,
         * but keeps a 3×3 window in registers and slides it along j.
         * ------------------------------------------------------------------ */

        /* Prime the 3×3 window with columns 0,1,2 (needed for j = 1). */
        DATA_TYPE top0 = Aim1[0];
        DATA_TYPE top1 = Aim1[1];
        DATA_TYPE top2 = Aim1[2];

        DATA_TYPE mid0 = Ai[0];
        DATA_TYPE mid1 = Ai[1];
        DATA_TYPE mid2 = Ai[2];

        DATA_TYPE bot0 = Aip1[0];
        DATA_TYPE bot1 = Aip1[1];
        DATA_TYPE bot2 = Aip1[2];

        int j = 1;
        const int last_minus_one = last - 1;

        /* Main loop: j = 1 .. last-1 (if last >= 2). Each iteration:
           - uses the current 3×3 window (top*, mid*, bot*)
           - computes A[i][j]
           - advances the window by one column to the right. */
#pragma GCC unroll 4
        for (; j <= last_minus_one; ++j)
        {
          const DATA_TYPE new_val =
            (top0 + top1 + top2 +
             mid0 + mid1 + mid2 +
             bot0 + bot1 + bot2) * inv9;

          /* In-place Gauss–Seidel update for A[i][j]. */
          Ai[j] = new_val;

          const int jp2 = j + 2;

          /* Advance the 3-wide window by one column:
             [j-1, j, j+1] -> [j, j+1, j+2]. */
          top0 = top1;
          top1 = top2;
          top2 = Aim1[jp2];

          mid0 = new_val;   /* Newly written A[i][j] is now the west neighbor */
          mid1 = mid2;
          mid2 = Ai[jp2];

          bot0 = bot1;
          bot1 = bot2;
          bot2 = Aip1[jp2];
        }

        /* Handle the last interior column j == last (== n_pb-2). At this
           point, the window already corresponds to the neighborhood of
           that column, so we just perform one final update. */
        {
          const DATA_TYPE new_val =
            (top0 + top1 + top2 +
             mid0 + mid1 + mid2 +
             bot0 + bot1 + bot2) * inv9;

          Ai[last] = new_val;
        }
      }
    }
  }
#pragma endscop

